<?php
declare(strict_types=1); require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Modules\Orders\OrderRepository; use App\Modules\Shops\ShopRepository; use App\Support\Auth; use App\Support\Csrf; use App\Support\Session; use function App\Support\e;
new App();$db=Database::connection();$merchant=Auth::requireMerchant($db);$shopId=(int)$merchant['id'];$repo=new OrderRepository($db);$id=(int)($_GET['id']??0);$order=$repo->findForShop($id,$shopId);if(!$order){http_response_code(404);exit('Order not found');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null)){Session::flash('error','Your form session expired. Please try again.');}else{$status=(string)($_POST['status']??'');if(!$repo->updateStatus($id,$shopId,$status))Session::flash('error','Order could not be updated.');else Session::flash('success','Order status updated.');}header('Location: /orders/view?id='.$id);exit;}
