?><div class="merchant-shell"><?php require dirname(__DIR__,2).'/app/Views/components/merchant-sidebar.php'; ?><main class="merchant-main"><div class="merchant-topbar"><div><a href="/orders" class="small text-secondary text-decoration-none"> Orders</a><h1 class="h3 fw-bold mb-0 mt-1">#<?=e($order['order_number'])?></h1></div><span class="status-badge status-<?=e($order['status'])?> align-self-start"><?=e(ucfirst($order['status']))?></span></div><?php require dirname(__DIR__,2).'/app/Views/components/alert.php'; ?><div class="row g-4"><div class="col-lg-8"><section class="panel p-4 mb-4"><div class="d-flex justify-content-between gap-3 mb-3"><div><h2 class="h5 fw-bold mb-1">Items</h2><p class="small text-secondary mb-0">Customer order summary.</p></div><div class="text-end"><div class="small text-secondary">Total</div><div class="h5 fw-bold mb-0"><?=e($order['currency'])?> <?=number_format((float)$order['total'],2)?></div></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($order['items'] as $item): ?><tr><td><div class="fw-semibold"><?=e($item['product_name'])?></div><?php if($item['sku']): ?><div class="small text-secondary">SKU <?=e($item['sku'])?></div><?php endif;?></td><td><?=number_format((int)$item['quantity'])?></td><td><?=e($order['currency'])?> <?=number_format((float)$item['unit_price'],2)?></td><td><?=e($order['currency'])?> <?=number_format((float)$item['line_total'],2)?></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-end"><div style="min-width:220px"><div class="d-flex justify-content-between small"><span>Subtotal</span><strong><?=e($order['currency'])?> <?=number_format((float)$order['subtotal'],2)?></strong></div><div class="d-flex justify-content-between small mt-2"><span>Delivery</span><strong><?=e($order['currency'])?> <?=number_format((float)$order['delivery_fee'],2)?></strong></div><hr><div class="d-flex justify-content-between"><strong>Total</strong><strong><?=e($order['currency'])?> <?=number_format((float)$order['total'],2)?></strong></div></div></div></section><?php if($order['status']!=='delivered'&&!in_array($order['status'],['cancelled','rejected'],true)): ?><section class="panel p-4"><h2 class="h5 fw-bold">Update order</h2><div class="d-flex flex-wrap gap-2 mt-3"><?php if(isset($next[$order['status']])):?><form method="post"><?=Csrf::field()?><input type="hidden" name="status" value="<?=e($next[$order['status']][0])?>"><button class="btn btn-primary"><?=e($next[$order['status']][1])?></button></form><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="status" value="cancelled"><button class="btn btn-outline-danger">Cancel order</button></form></div></section><?php endif;?></div><div class="col-lg-4"><section class="panel p-4 mb-4"><h2 class="h5 fw-bold">Customer</h2><div class="mt-3"><div class="fw-semibold"><?=e($order['customer_name'])?></div><div class="small text-secondary mt-1"><?=e($order['customer_phone'])?></div><?php if($order['customer_email']):?><div class="small text-secondary"><?=e($order['customer_email'])?></div><?php endif;?></div></section><section class="panel p-4 mb-4"><h2 class="h5 fw-bold"><?= $order['fulfillment_method'] === 'pickup' ? 'Pickup' : 'Delivery' ?></h2><?php if($order['fulfillment_method'] === 'pickup'): ?><div class="small text-secondary mt-3">Customer will collect this order from the store.</div><?php else: ?><p class="small text-secondary mt-3 mb-0"><?=nl2br(e($order['delivery_address']?:'No delivery address provided.'))?></p><?php if($order['delivery_zone_name']): ?><div class="small mt-2"><strong>Area:</strong> <?=e($order['delivery_zone_name'])?></div><?php endif; ?><?php endif; ?><?php if($order['notes']):?><hr><div class="small"><strong>Notes</strong><div class="text-secondary mt-1"><?=nl2br(e($order['notes']))?></div></div><?php endif;?></section><section class="panel p-4"><h2 class="h5 fw-bold">Payment</h2><div class="d-flex justify-content-between mt-3"><span class="small text-secondary">Method</span><strong><?=e(ucwords(str_replace('_',' ',$order['payment_method'])))?></strong></div><div class="d-flex justify-content-between mt-2"><span class="small text-secondary">Status</span><span class="status-badge status-<?=e($order['payment_status'])?>"><?=e(ucfirst($order['payment_status']))?></span></div></section></div></div></main></div><?php $content=ob_get_clean();$title='Order #'.$order['order_number'];$merchantLayout=true;require dirname(__DIR__,2).'/app/Views/layouts/app.php';
